window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-20e6178758a271e6"]={"versions": [{"id": "FIG-20e6178758a271e6", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des FlexRay Transport-Protokolls (FrTp) innerhalb der AUTOSAR Classic Platform (Communication Stack / BSW). Dargestellt ist der Ablauf einer segmentierten 1:1-Punkt-zu-Punkt-Übertragung mit Empfangsbestätigung (Acknowledgement) und ohne Wiederholungsmechanismus (without Retry).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Kommunikationsentitäten sind zwei FrTp-Instanzen:</p>\n<ul class=\"fig-list\">\n<li><code>Sender</code>: Sendende FrTp-Instanz.</li>\n<li><code>Receiver</code>: Empfangende FrTp-Instanz.</li>\n</ul>\n<p class=\"fig-p\">Ausgetauschte N-PDUs (Protokollnachrichten) über das FlexRay-Kommunikationsnetzwerk:</p>\n<ul class=\"fig-list\">\n<li><code>FF</code> (First Frame): Beginn der segmentierten Datenübertragung durch den Sender.</li>\n<li><code>FC (CTS)</code> (Flow Control - Clear to Send): Flusskontrollrahmen des Empfängers zur Freigabe des nächsten Übertragungsblocks.</li>\n<li><code>CF</code> (Consecutive Frame): Aufeinanderfolgende Datensegmente vom Sender zum Empfänger.</li>\n<li><code>AF (Positive Acknowledge)</code> (Acknowledgement Frame): Quittierungsnachricht des Empfängers zum positiven Abschluss der Gesamtnachricht.</li>\n<li>Konfigurationsparameter: <code>FrTp_BS = 1...16</code> (Block Size), definiert die Anzahl aufeinanderfolgender <code>CF</code>, die vor dem Warten auf das nächste <code>FC (CTS)</code> übertragen werden dürfen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Übertragung beginnt mit dem Senden eines <code>FF</code> vom Sender an den Empfänger.</li>\n<li>Der Empfänger quittiert den Empfang des <code>FF</code> und steuert den weiteren Datenfluss mittels eines <code>FC (CTS)</code>-Rahmens.</li>\n<li>Der Sender überträgt daraufhin einen Block von <code>CF</code> (Consecutive Frames), dessen Umfang durch <code>FrTp_BS</code> (Wertebereich 1 bis 16) begrenzt ist.</li>\n<li>Nach Abschluss jedes Blocks sendet der Empfänger erneut einen <code>FC (CTS)</code>, woraufhin der Sender den nächsten Block an <code>CF</code> überträgt. Diese Blockübertragungssequenz wiederholt sich bis zum letzten Datensegment (angedeutet durch vertikale Auslassungspunkte <code>...</code>).</li>\n<li>Nach dem Empfang des letzten <code>CF</code> der Gesamtnachricht sendet der Empfänger einen abschließenden <code>AF (Positive Acknowledge)</code> an den Sender zurück, womit die Übertragung erfolgreich beendet wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Protokollverhalten für FrTp-Verbindungen im Betriebsmodus mit Quittierung ohne Neuübertragung (Ack without Retry). Wesentliche Entwicklungsaspekte:</p>\n<ul class=\"fig-list\">\n<li>Die Blockgröße <code>FrTp_BS</code> muss im Bereich von 1 bis 16 konfiguriert werden; der Sender darf ohne zwischenzeitliches <code>FC (CTS)</code> maximal die spezifizierte Anzahl an <code>CF</code> absetzen.</li>\n<li>Bei diesem Modus führt der Verlust eines Frames oder das Ausbleiben der Quittung mangels Retry-Mechanismus unmittelbar zum Verbindungs- bzw. Übertragungsabbruch mit Fehlermeldung an obere Schichten (PduR).</li>\n<li>Der Empfänger muss über ausreichende Pufferkapazitäten zur Aufnahme der durch <code>FrTp_BS</code> festgelegten Blockgröße verfügen, bevor er <code>FC (CTS)</code> signalisiert.</li>\n<li>Der Sender muss nach dem Senden des letzten <code>CF</code> auf den Empfang des <code>AF (Positive Acknowledge)</code> warten, bevor der PDU-Sendeauftrag als erfolgreich abgeschlossen (<code>E_OK</code>) an den PDU-Router gemeldet werden kann.</li>\n</ul>"}, {"id": "FIG-5661dccfb15e142e", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm zur Spezifikation des FlexRay Transport-Protokolls (FrTp) innerhalb der AUTOSAR Classic Platform (Communication Stack / BSW). Dargestellt ist der Ablauf einer segmentierten 1:1-Punkt-zu-Punkt-Übertragung mit Empfangsbestätigung (Acknowledgement) und ohne Wiederholungsmechanismus (without Retry).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Beteiligte Kommunikationsentitäten sind zwei FrTp-Instanzen:</p>\n<ul class=\"fig-list\">\n<li><code>Sender</code>: Sendende FrTp-Instanz.</li>\n<li><code>Receiver</code>: Empfangende FrTp-Instanz.</li>\n</ul>\n<p class=\"fig-p\">Ausgetauschte N-PDUs (Protokollnachrichten) über das FlexRay-Kommunikationsnetzwerk:</p>\n<ul class=\"fig-list\">\n<li><code>FF</code> (First Frame): Beginn der segmentierten Datenübertragung durch den Sender.</li>\n<li><code>FC (CTS)</code> (Flow Control - Clear to Send): Flusskontrollrahmen des Empfängers zur Freigabe des nächsten Übertragungsblocks.</li>\n<li><code>CF</code> (Consecutive Frame): Aufeinanderfolgende Datensegmente vom Sender zum Empfänger.</li>\n<li><code>AF (Positive Acknowledge)</code> (Acknowledgement Frame): Quittierungsnachricht des Empfängers zum positiven Abschluss der Gesamtnachricht.</li>\n<li>Konfigurationsparameter: <code>FrTp_BS = 1...16</code> (Block Size), definiert die Anzahl aufeinanderfolgender <code>CF</code>, die vor dem Warten auf das nächste <code>FC (CTS)</code> übertragen werden dürfen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die Übertragung beginnt mit dem Senden eines <code>FF</code> vom Sender an den Empfänger.</li>\n<li>Der Empfänger quittiert den Empfang des <code>FF</code> und steuert den weiteren Datenfluss mittels eines <code>FC (CTS)</code>-Rahmens.</li>\n<li>Der Sender überträgt daraufhin einen Block von <code>CF</code> (Consecutive Frames), dessen Umfang durch <code>FrTp_BS</code> (Wertebereich 1 bis 16) begrenzt ist.</li>\n<li>Nach Abschluss jedes Blocks sendet der Empfänger erneut einen <code>FC (CTS)</code>, woraufhin der Sender den nächsten Block an <code>CF</code> überträgt. Diese Blockübertragungssequenz wiederholt sich bis zum letzten Datensegment (angedeutet durch vertikale Auslassungspunkte <code>...</code>).</li>\n<li>Nach dem Empfang des letzten <code>CF</code> der Gesamtnachricht sendet der Empfänger einen abschließenden <code>AF (Positive Acknowledge)</code> an den Sender zurück, womit die Übertragung erfolgreich beendet wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das Protokollverhalten für FrTp-Verbindungen im Betriebsmodus mit Quittierung ohne Neuübertragung (Ack without Retry). Wesentliche Entwicklungsaspekte:</p>\n<ul class=\"fig-list\">\n<li>Die Blockgröße <code>FrTp_BS</code> muss im Bereich von 1 bis 16 konfiguriert werden; der Sender darf ohne zwischenzeitliches <code>FC (CTS)</code> maximal die spezifizierte Anzahl an <code>CF</code> absetzen.</li>\n<li>Bei diesem Modus führt der Verlust eines Frames oder das Ausbleiben der Quittung mangels Retry-Mechanismus unmittelbar zum Verbindungs- bzw. Übertragungsabbruch mit Fehlermeldung an obere Schichten (PduR).</li>\n<li>Der Empfänger muss über ausreichende Pufferkapazitäten zur Aufnahme der durch <code>FrTp_BS</code> festgelegten Blockgröße verfügen, bevor er <code>FC (CTS)</code> signalisiert.</li>\n<li>Der Sender muss nach dem Senden des letzten <code>CF</code> auf den Empfang des <code>AF (Positive Acknowledge)</code> warten, bevor der PDU-Sendeauftrag als erfolgreich abgeschlossen (<code>E_OK</code>) an den PDU-Router gemeldet werden kann.</li>\n</ul>"}], "trans": [{"from": "FIG-20e6178758a271e6", "to": "FIG-5661dccfb15e142e", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
